import re
from decimal import Decimal
from typing import Optional

_MULTIPLIERS = {
    "k": Decimal("1000"),
    "mil": Decimal("1000"),
    "m": Decimal("1000000"),
    "mi": Decimal("1000000"),
    "milhão": Decimal("1000000"),
    "milhao": Decimal("1000000"),
    "milhões": Decimal("1000000"),
    "milhoes": Decimal("1000000"),
    "b": Decimal("1000000000"),
    "bi": Decimal("1000000000"),
    "bilhão": Decimal("1000000000"),
    "bilhao": Decimal("1000000000"),
    "bilhões": Decimal("1000000000"),
    "bilhoes": Decimal("1000000000"),
}

_NUM_REGEX = re.compile(
    r"(?P<num>\d+(?:[.,]\d+)*)"
    r"(?:\s*(?P<suf>milh[õo]es|milh[ãa]o|bilh[õo]es|bilh[ãa]o|mil|mi|bi|k|m|b)\b)?",
    re.IGNORECASE,
)

_ZERO_REGEX = re.compile(r"\b(?:nenhum|nenhuma|sem)\b", re.IGNORECASE)


def numero(txt: Optional[str]) -> Optional[int]:
    if not txt or not isinstance(txt, str):
        return None

    clean_txt = txt.replace("\xa0", " ").strip()
    if not clean_txt:
        return None

    match = _NUM_REGEX.search(clean_txt)
    if not match:
        if _ZERO_REGEX.search(clean_txt):
            return 0
        return None

    num_str = match.group("num")
    suf = match.group("suf")

    if suf:
        suf_lower = suf.lower()
        mult = _MULTIPLIERS[suf_lower]

        if "," in num_str and "." in num_str:
            if num_str.rfind(",") > num_str.rfind("."):
                norm_num = num_str.replace(".", "").replace(",", ".")
            else:
                norm_num = num_str.replace(",", "")
        elif "," in num_str:
            if num_str.count(",") == 1:
                norm_num = num_str.replace(",", ".")
            else:
                norm_num = num_str.replace(",", "")
        elif "." in num_str:
            if num_str.count(".") == 1:
                norm_num = num_str
            else:
                norm_num = num_str.replace(".", "")
        else:
            norm_num = num_str

        return int(Decimal(norm_num) * mult)
    else:
        if "," in num_str and "." in num_str:
            if num_str.rfind(",") > num_str.rfind("."):
                norm_num = num_str.replace(".", "").replace(",", ".")
            else:
                norm_num = num_str.replace(",", "")
            return int(Decimal(norm_num))
        elif "," in num_str:
            parts = num_str.split(",")
            if all(len(p) == 3 for p in parts[1:]):
                return int(num_str.replace(",", ""))
            return int(Decimal(num_str.replace(",", ".")))
        elif "." in num_str:
            parts = num_str.split(".")
            if all(len(p) == 3 for p in parts[1:]):
                return int(num_str.replace(".", ""))
            return int(Decimal(num_str))
        else:
            return int(num_str)

from datetime import datetime, timedelta
from typing import Iterable, Optional


def proximo_horario(
    horarios: Iterable[str],
    agora: datetime,
    margem_min: int = 25,
    ocupados: Iterable[datetime] = (),
) -> Optional[datetime]:
    horarios_validos = set()
    for h in horarios:
        if not isinstance(h, str):
            continue
        partes = h.strip().split(":")
        if len(partes) != 2:
            continue
        try:
            hora = int(partes[0])
            minuto = int(partes[1])
            if 0 <= hora <= 23 and 0 <= minuto <= 59:
                horarios_validos.add((hora, minuto))
        except ValueError:
            continue

    if not horarios_validos:
        return None

    horarios_ordenados = sorted(horarios_validos)
    limite_minimo = agora + timedelta(minutes=margem_min)
    ocupados_set = set(ocupados)
    data_base = agora.replace(hour=0, minute=0, second=0, microsecond=0)

    for dias in range(8):
        dia_atual = data_base + timedelta(days=dias)
        for hora, minuto in horarios_ordenados:
            candidato = dia_atual.replace(hour=hora, minute=minuto)
            if candidato >= limite_minimo and candidato not in ocupados_set:
                return candidato

    return None

from datetime import timedelta


class Pausa:
    def __init__(self):
        self.minutos = 0
        self.fim = None

    def bloqueio(self, agora):
        if self.fim is not None and agora - self.fim <= timedelta(minutes=60):
            self.minutos = min(self.minutos * 2, 120)
        else:
            self.minutos = 20
        self.fim = agora + timedelta(minutes=self.minutos)
        return self.minutos

    def pode_rodar(self, agora):
        return self.fim is None or agora >= self.fim

import json


def extrair_texto(body: str) -> str:
    if not isinstance(body, str):
        return ""

    maior_texto = ""

    for linha in body.splitlines():
        linha = linha.strip()
        if not linha or linha == ")]}'" or linha.isdigit():
            continue

        try:
            bloco = json.loads(linha)
        except (ValueError, TypeError):
            continue

        if not isinstance(bloco, list):
            continue

        for entrada in bloco:
            if not isinstance(entrada, list) or len(entrada) < 3:
                continue

            if entrada[0] != "wrb.fr" or not isinstance(entrada[2], str):
                continue

            try:
                interno = json.loads(entrada[2])
                texto = interno[4][0][1][0]
                if isinstance(texto, str) and len(texto) > len(maior_texto):
                    maior_texto = texto
            except (ValueError, TypeError, IndexError, KeyError):
                continue

    return maior_texto

import calendar
from datetime import datetime, timedelta
from typing import Optional, Set

MESES = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4,
    "may": 5, "jun": 6, "jul": 7, "aug": 8,
    "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

DIAS_SEMANA = {
    "sun": 0, "mon": 1, "tue": 2, "wed": 3,
    "thu": 4, "fri": 5, "sat": 6,
}


def _converter_valor(token: str, min_val: int, max_val: int, nomes: Optional[dict] = None) -> int:
    if not token:
        raise ValueError("Token vazio")
    t_lower = token.lower()
    if nomes and t_lower in nomes:
        val = nomes[t_lower]
    else:
        if not token.isdigit():
            raise ValueError(f"Valor numérico inválido: {token}")
        val = int(token)
    if val < min_val or val > max_val:
        raise ValueError(f"Valor {val} fora da faixa permitida [{min_val}, {max_val}]")
    return val


def _parse_campo(
    campo: str,
    min_val: int,
    max_val: int,
    nomes: Optional[dict] = None,
    eh_dow: bool = False,
) -> Set[int]:
    if not campo:
        raise ValueError("Campo vazio")

    resultado: Set[int] = set()
    partes = campo.split(",")
    if any(p == "" for p in partes):
        raise ValueError(f"Lista malformada no campo: {campo}")

    for parte in partes:
        if "/" in parte:
            subpartes = parte.split("/")
            if len(subpartes) != 2 or not subpartes[0] or not subpartes[1]:
                raise ValueError(f"Sintaxe de passo inválida: {parte}")
            base, passo_str = subpartes
            if not passo_str.isdigit():
                raise ValueError(f"Passo inválido: {passo_str}")
            passo = int(passo_str)
            if passo <= 0:
                raise ValueError("Passo deve ser maior que zero")
        else:
            base = parte
            passo = 1

        if base == "*":
            inicio, fim = min_val, (6 if eh_dow else max_val)
        elif "-" in base:
            limites = base.split("-")
            if len(limites) != 2 or not limites[0] or not limites[1]:
                raise ValueError(f"Faixa inválida: {base}")
            inicio = _converter_valor(limites[0], min_val, max_val, nomes)
            fim = _converter_valor(limites[1], min_val, max_val, nomes)
            if inicio > fim:
                raise ValueError(f"Início da faixa maior que o fim: {base}")
        else:
            if "/" in parte:
                raise ValueError(f"Passo não permitido em valor único: {parte}")
            val = _converter_valor(base, min_val, max_val, nomes)
            inicio = fim = val

        for v in range(inicio, fim + 1, passo):
            if eh_dow and v == 7:
                resultado.add(0)
            else:
                resultado.add(v)

    return resultado


def proxima_execucao(expr: str, agora: datetime) -> Optional[datetime]:
    if not isinstance(expr, str):
        raise ValueError("A expressão deve ser uma string")
    if "\n" in expr or "\r" in expr:
        raise ValueError("Quebras de linha não são permitidas na expressão")

    partes = expr.strip().split()
    if len(partes) != 5:
        raise ValueError("A expressão cron deve conter exatamente 5 campos")

    min_str, hora_str, dom_str, mes_str, dow_str = partes

    minutos = sorted(_parse_campo(min_str, 0, 59))
    horas = sorted(_parse_campo(hora_str, 0, 23))
    dias_mes = _parse_campo(dom_str, 1, 31)
    meses = sorted(_parse_campo(mes_str, 1, 12, nomes=MESES))
    dias_semana = _parse_campo(dow_str, 0, 7, nomes=DIAS_SEMANA, eh_dow=True)

    dom_asterisco = (dom_str == "*")
    dow_asterisco = (dow_str == "*")

    try:
        limite = agora.replace(year=agora.year + 5)
    except ValueError:
        # Caso agora seja 29 de fevereiro e daqui a 5 anos não seja bissexto
        limite = agora.replace(year=agora.year + 5, day=28)

    candidato = (agora + timedelta(minutes=1)).replace(second=0, microsecond=0)

    def dia_bate(ano: int, mes: int, dia: int) -> bool:
        # Em Python: Monday=0 .. Sunday=6 -> converter para Sunday=0 .. Saturday=6
        dow_cron = (datetime(ano, mes, dia, tzinfo=agora.tzinfo).weekday() + 1) % 7
        match_dom = dia in dias_mes
        match_dow = dow_cron in dias_semana

        if not dom_asterisco and not dow_asterisco:
            return match_dom or match_dow
        elif not dom_asterisco:
            return match_dom
        elif not dow_asterisco:
            return match_dow
        return True

    ano = candidato.year
    ano_max = limite.year

    while ano <= ano_max:
        for mes in meses:
            if ano == candidato.year and mes < candidato.month:
                continue

             _, max_dia_mes = calendar.monthrange(ano, mes)
            dia_inicial = candidato.day if (ano == candidato.year and mes == candidato.month) else 1

            for dia in range(dia_inicial, max_dia_mes + 1):
                if not dia_bate(ano, mes, dia):
                    continue

                eh_dia_inicial = (ano == candidato.year and mes == candidato.month and dia == candidato.day)

                for hora in horas:
                    if eh_dia_inicial and hora < candidato.hour:
                        continue

                    eh_hora_inicial = eh_dia_inicial and (hora == candidato.hour)

                    for minuto in minutos:
                        if eh_hora_inicial and minuto < candidato.minute:
                            continue

                        res = candidato.replace(year=ano, month=mes, day=dia, hour=hora, minute=minuto)
                        if res > limite:
                            return None
                        return res
        ano += 1

    return None

