import re

_HUNK_RE = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@")


def aplicar_patch(texto: str, diff: str) -> str:
    linhas_arquivo = texto.splitlines(keepends=True)
    linhas_diff = diff.splitlines(keepends=False)

    hunks = []
    i = 0
    n = len(linhas_diff)

    while i < n:
        linha = linhas_diff[i]
        if linha.startswith("--- ") or linha.startswith("+++ "):
            i += 1
            continue
        m = _HUNK_RE.match(linha)
        if m:
            old_start = int(m.group(1))
            old_count = int(m.group(2)) if m.group(2) is not None else 1
            new_start = int(m.group(3))
            new_count = int(m.group(4)) if m.group(4) is not None else 1
            i += 1

            old_block = []
            new_block = []
            last_type = None

            while i < n:
                hl = linhas_diff[i]
                if _HUNK_RE.match(hl) or hl.startswith("--- ") or hl.startswith("+++ "):
                    break
                if hl.startswith("\\"):
                    if last_type == " ":
                        if old_block and old_block[-1].endswith("\n"):
                            old_block[-1] = old_block[-1][:-1]
                        if new_block and new_block[-1].endswith("\n"):
                            new_block[-1] = new_block[-1][:-1]
                    elif last_type == "-":
                        if old_block and old_block[-1].endswith("\n"):
                            old_block[-1] = old_block[-1][:-1]
                    elif last_type == "+":
                        if new_block and new_block[-1].endswith("\n"):
                            new_block[-1] = new_block[-1][:-1]
                    i += 1
                    continue

                if hl == "":
                    prefix = " "
                    conteudo = "\n"
                else:
                    prefix = hl[0]
                    conteudo = hl[1:] + "\n"

                if prefix == " ":
                    old_block.append(conteudo)
                    new_block.append(conteudo)
                    last_type = " "
                elif prefix == "-":
                    old_block.append(conteudo)
                    last_type = "-"
                elif prefix == "+":
                    new_block.append(conteudo)
                    last_type = "+"
                else:
                    break
                i += 1

            hunks.append((old_start, old_count, new_start, new_count, old_block, new_block))
        else:
            i += 1

    offset = 0
    min_pos = 0

    for old_start, old_count, new_start, new_count, old_block, new_block in hunks:
        tam_old = len(old_block)
        if old_start == 0 and tam_old == 0:
            pos_esperada = 0
        else:
            pos_esperada = max(0, old_start - 1 + offset)

        if tam_old == 0:
            melhor_pos = max(min_pos, min(pos_esperada, len(linhas_arquivo)))
        else:
            limite = len(linhas_arquivo) - tam_old
            if limite < min_pos:
                raise ValueError("Hunk maior que o restante do arquivo.")

            if (
                min_pos <= pos_esperada <= limite
                and linhas_arquivo[pos_esperada : pos_esperada + tam_old] == old_block
            ):
                melhor_pos = pos_esperada
            else:
                candidatos = [
                    p
                    for p in range(min_pos, limite + 1)
                    if linhas_arquivo[p : p + tam_old] == old_block
                ]
                if not candidatos:
                    raise ValueError("Contexto do hunk não encontrado no arquivo.")
                melhor_pos = min(candidatos, key=lambda p: (abs(p - pos_esperada), p))

        linhas_arquivo[melhor_pos : melhor_pos + tam_old] = new_block
        offset += len(new_block) - tam_old
        min_pos = melhor_pos + len(new_block)

    return "".join(linhas_arquivo)

import re
from typing import List, Tuple, Union

Token = Tuple[str, Union[str, int, float]]

_TOKEN_REGEX = re.compile(
    r'(?P<WS>\s+)|'
    r'(?P<FLOAT>'
        r'(?:\d+\.\d*|\.\d+)(?:[eE][+-]?\d+)?|'
        r'\d+[eE][+-]?\d+'
    r')|'
    r'(?P<INT>\d+)|'
    r'(?P<OP>\*\*|//|[+\-*/%])|'
    r'(?P<LPAREN>\()|'
    r'(?P<RPAREN>\))|'
    r'(?P<ERR>.)',
    re.DOTALL
)

def _tokenize(expr: str) -> List[Token]:
    if not isinstance(expr, str):
        raise ValueError("A expressão deve ser uma string.")

    tokens: List[Token] = []
    pos = 0
    n = len(expr)

    while pos < n:
        match = _TOKEN_REGEX.match(expr, pos)
        if not match:
            raise ValueError(f"Erro na análise léxica na posição {pos}")

        kind = match.lastgroup
        val = match.group()

        # No Python, um número não pode ser seguido imediatamente por um ponto ou dígito (ex: `1.2.3`, `5..2`)
        if kind in ('FLOAT', 'INT'):
            end_pos = match.end()
            if end_pos < n and (expr[end_pos] == '.' or expr[end_pos].isdigit()):
                raise ValueError(f"Literal numérico malformado perto de '{val}'")

        pos = match.end()

        if kind == 'WS':
            continue
        elif kind == 'ERR':
            raise ValueError(f"Caractere inválido: '{val}'")
        elif kind == 'INT':
            if len(val) > 1 and val.startswith('0'):
                raise ValueError(f"Zeros à esquerda não são permitidos em inteiros: '{val}'")
            tokens.append(('NUMBER', int(val)))
        elif kind == 'FLOAT':
            tokens.append(('NUMBER', float(val)))
        elif kind in ('OP', 'LPAREN', 'RPAREN'):
            tokens.append((kind, val))

    tokens.append(('EOF', ''))
    return tokens


class _Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        return self.tokens[self.pos]

    def consume(self, expected_type: str = None, expected_val: str = None) -> Token:
        tok = self.current()
        if expected_type and tok[0] != expected_type:
            raise ValueError(f"Esperado tipo {expected_type}, encontrado {tok[0]}")
        if expected_val and tok[1] != expected_val:
            raise ValueError(f"Esperado '{expected_val}', encontrado '{tok[1]}'")
        self.pos += 1
        return tok

    def parse(self) -> Union[int, float]:
        if self.current()[0] == 'EOF':
            raise ValueError("Expressão vazia")
        res = self.expr()
        if self.current()[0] != 'EOF':
            raise ValueError(f"Token inesperado ao final da expressão: '{self.current()[1]}'")
        return res

    def expr(self) -> Union[int, float]:
        # expr := term (( '+' | '-' ) term)*
        left = self.term()
        while self.current()[0] == 'OP' and self.current()[1] in ('+', '-'):
            op = self.consume()[1]
            right = self.term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def term(self) -> Union[int, float]:
        # term := factor (( '*' | '/' | '//' | '%' ) factor)*
        left = self.factor()
        while self.current()[0] == 'OP' and self.current()[1] in ('*', '/', '//', '%'):
            op = self.consume()[1]
            right = self.factor()
            if op == '*':
                left = left * right
            elif op == '/':
                left = left / right
            elif op == '//':
                left = left // right
            elif op == '%':
                left = left % right
        return left

    def factor(self) -> Union[int, float]:
        # factor := ( '+' | '-' ) factor | power
        tok = self.current()
        if tok[0] == 'OP' and tok[1] in ('+', '-'):
            op = self.consume()[1]
            val = self.factor()
            return +val if op == '+' else -val
        return self.power()

    def power(self) -> Union[int, float]:
        # power := atom ( '**' factor )?
        left = self.atom()
        if self.current()[0] == 'OP' and self.current()[1] == '**':
            self.consume()
            right = self.factor()
            res = left ** right
            if isinstance(res, complex):
                raise ValueError("Resultado complexo não suportado para avaliação aritmética real")
            return res
        return left

    def atom(self) -> Union[int, float]:
        # atom := NUMBER | '(' expr ')'
        tok = self.current()
        if tok[0] == 'NUMBER':
            self.consume()
            return tok[1]
        elif tok[0] == 'LPAREN':
            self.consume('LPAREN')
            if self.current()[0] == 'RPAREN':
                raise ValueError("Parênteses vazios não são permitidos")
            val = self.expr()
            if self.current()[0] != 'RPAREN':
                raise ValueError("Parêntese de fechamento ')' esperado")
            self.consume('RPAREN')
            return val
        else:
            raise ValueError(f"Token inesperado na expressão: '{tok[1]}'")


def calcular(expr: str) -> Union[int, float]:
    tokens = _tokenize(expr)
    parser = _Parser(tokens)
    return parser.parse()

import re
from decimal import Decimal, InvalidOperation

_MULT = {
    "k": 10**3, "mil": 10**3,
    "m": 10**6, "mi": 10**6,
    "b": 10**9, "bi": 10**9,
}

_RE_NUM = re.compile(
    r"(\d[\d.,]*)\s*"
    r"(mil(?!h)|mi(?:lh(?:ões|ão|oes|ao))?|bi(?:lh(?:ões|ão|oes|ao))?|k|m|b)?"
    r"(?![a-zà-ÿ])",
    re.IGNORECASE,
)

_RE_ZERO = re.compile(r"\bnenhum|\bsem\b", re.IGNORECASE)

def _suffix_key(suf):
    if not suf:
        return None
    s = suf.lower()
    if s.startswith("mil") and not s.startswith("milh"):
        return "mil"
    if s.startswith("mi"):
        return "mi"
    if s.startswith("bi"):
        return "bi"
    return s

def _parse_number(raw, has_suffix):
    raw = raw.rstrip(".,")
    if not raw:
        return None
    has_dot = "." in raw
    has_comma = "," in raw

    if has_dot and has_comma:
        # o último separador é decimal, os demais são de milhar
        last = max(raw.rfind("."), raw.rfind(","))
        inteiro = re.sub(r"[.,]", "", raw[:last])
        decimal = raw[last + 1:]
        texto = f"{inteiro}.{decimal}"
    elif has_dot or has_comma:
        sep = "." if has_dot else ","
        partes = raw.split(sep)
        if len(partes) > 2:
            # vários separadores iguais: milhar
            texto = "".join(partes)
        elif has_suffix:
            # um único separador antes de sufixo: decimal
            texto = f"{partes[0]}.{partes[1]}"
        elif len(partes[1]) == 3:
            # "12.345" / "12,345" sem sufixo: milhar
            texto = partes[0] + partes[1]
        else:
            texto = f"{partes[0]}.{partes[1]}"
    else:
        texto = raw

    try:
        return Decimal(texto)
    except InvalidOperation:
        return None

def numero(txt):
    if txt is None:
        return None
    if not isinstance(txt, str):
        txt = str(txt)
    t = txt.replace("\xa0", " ").replace("\u202f", " ").strip()
    if not t:
        return None

    m = _RE_NUM.search(t)
    if not m:
        if _RE_ZERO.search(t):
            return 0
        return None

    key = _suffix_key(m.group(2))
    valor = _parse_number(m.group(1), key is not None)
    if valor is None:
        if _RE_ZERO.search(t):
            return 0
        return None

    mult = _MULT.get(key, 1) if key else 1
    return int(valor * mult)

import re
from datetime import datetime, timedelta, time

_PADRAO_HORARIO = re.compile(r"(\d{1,2}):(\d{2})", re.ASCII)

def _parse_horario(valor):
    """Converte 'HH:MM' em datetime.time; retorna None se inválido."""
    if not isinstance(valor, str):
        return None
    m = _PADRAO_HORARIO.fullmatch(valor.strip())
    if not m:
        return None
    h, mi = int(m.group(1)), int(m.group(2))
    if not (0 <= h <= 23 and 0 <= mi <= 59):
        return None
    return time(h, mi)

def _normalizar(dt):
    return dt.replace(second=0, microsecond=0)

def proximo_horario(horarios, agora, margem_min=25, ocupados=()):
    """
    Retorna o primeiro datetime (segundos/microssegundos zerados), a partir de hoje
    e até hoje + 7 dias, cujo horário esteja em `horarios`, que seja
    >= agora + margem_min minutos e que não esteja em `ocupados`.
    Retorna None se nada for encontrado ou se não houver horários válidos.
    """
    if not horarios:
        return None

    tempos = sorted({t for t in (_parse_horario(h) for h in horarios) if t is not None})
    if not tempos:
        return None

    limite = agora + timedelta(minutes=margem_min)

    ocupados_norm = set()
    for o in ocupados or ():
        if isinstance(o, datetime):
            ocupados_norm.add(_normalizar(o))

    hoje = agora.date()
    for delta_dias in range(0, 8):  # hoje + 7 dias
        dia = hoje + timedelta(days=delta_dias)
        for t in tempos:
            candidato = datetime.combine(dia, t)
            if candidato < limite:
                continue
            if candidato in ocupados_norm:
                continue
            return candidato

    return None

from datetime import timedelta

class Pausa:
    PAUSA_INICIAL = 20
    TETO = 120
    JANELA = timedelta(minutes=60)

    def __init__(self):
        self.minutos = 0
        self.fim = None

    def bloqueio(self, agora):
        # Novo bloqueio durante a pausa (agora < fim) ou em até 60 min após o fim: dobra
        if self.fim is not None and agora - self.fim <= self.JANELA:
            self.minutos = min(self.minutos * 2, self.TETO)
        else:
            self.minutos = self.PAUSA_INICIAL
        self.fim = agora + timedelta(minutes=self.minutos)
        return self.minutos

    def pode_rodar(self, agora):
        return self.fim is None or agora >= self.fim

import json
from typing import Any

def _caminho_texto(interno: Any) -> str | None:
    """Extrai interno[4][0][1][0] com checagem de tipos; devolve None se falhar."""
    try:
        if not isinstance(interno, list):
            return None
        n4 = interno[4]
        if not isinstance(n4, list):
            return None
        n40 = n4[0]
        if not isinstance(n40, list):
            return None
        n401 = n40[1]
        if not isinstance(n401, list):
            return None
        texto = n401[0]
        if isinstance(texto, str):
            return texto
    except (IndexError, TypeError, KeyError):
        pass
    return None

def extrair_texto(body: str) -> str:
    if not isinstance(body, str) or not body:
        return ""

    texto_body = body.lstrip("\ufeff")
    prefixo = ")]}'"
    if texto_body.lstrip().startswith(prefixo):
        texto_body = texto_body.lstrip()[len(prefixo):]

    melhor = ""

    for linha in texto_body.splitlines():
        linha = linha.strip()
        if not linha or not linha.startswith("["):
            continue
        try:
            dados = json.loads(linha)
        except (ValueError, TypeError):
            continue
        if not isinstance(dados, list):
            continue

        for entrada in dados:
            if not isinstance(entrada, list) or not entrada:
                continue
            if entrada[0] != "wrb.fr":
                continue
            if len(entrada) < 3:
                continue
            bruto = entrada[2]
            if not isinstance(bruto, str):
                continue
            try:
                interno = json.loads(bruto)
            except (ValueError, TypeError):
                continue
            texto = _caminho_texto(interno)
            if texto is not None and len(texto) > len(melhor):
                melhor = texto

    return melhor

import re
from datetime import datetime, timedelta, time

_MESES = {n: i + 1 for i, n in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun",
     "jul", "aug", "sep", "oct", "nov", "dec"])}
_DIAS = {n: i for i, n in enumerate(
    ["sun", "mon", "tue", "wed", "thu", "fri", "sat"])}

_NUM_RE = re.compile(r"[0-9]+")

def _valor(tok, lo, hi, nomes):
    t = tok.strip().lower()
    if nomes and t in nomes:
        v = nomes[t]
    elif _NUM_RE.fullmatch(t):
        v = int(t)
    else:
        raise ValueError("valor inválido: %r" % tok)
    if v < lo or v > hi:
        raise ValueError("valor fora da faixa: %r" % tok)
    return v

def _parse_campo(campo, lo, hi, nomes=None):
    if not campo:
        raise ValueError("campo vazio")
    valores = set()
    for item in campo.split(","):
        if not item:
            raise ValueError("item vazio em %r" % campo)
        partes = item.split("/")
        if len(partes) > 2:
            raise ValueError("passo inválido: %r" % item)
        base = partes[0]
        passo = 1
        tem_passo = len(partes) == 2
        if tem_passo:
            if not _NUM_RE.fullmatch(partes[1]):
                raise ValueError("passo inválido: %r" % item)
            passo = int(partes[1])
            if passo <= 0:
                raise ValueError("passo zero: %r" % item)
        if base == "*":
            a, b = lo, hi
        elif "-" in base:
            ab = base.split("-")
            if len(ab) != 2:
                raise ValueError("faixa inválida: %r" % item)
            a = _valor(ab[0], lo, hi, nomes)
            b = _valor(ab[1], lo, hi, nomes)
            if a > b:
                raise ValueError("faixa invertida: %r" % item)
        else:
            a = _valor(base, lo, hi, nomes)
            b = hi if tem_passo else a
        valores.update(range(a, b + 1, passo))
    return valores

def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError("expressão deve ser string")
    campos = expr.split()
    if len(campos) != 5:
        raise ValueError("expressão deve ter 5 campos")
    minutos = _parse_campo(campos[0], 0, 59)
    horas = _parse_campo(campos[1], 0, 23)
    dom = _parse_campo(campos[2], 1, 31)
    meses = _parse_campo(campos[3], 1, 12, _MESES)
    dow = _parse_campo(campos[4], 0, 7, _DIAS)
    if 7 in dow:
        dow.discard(7)
        dow.add(0)
    dom_star = campos[2].startswith("*")
    dow_star = campos[4].startswith("*")
    return (sorted(minutos), sorted(horas), dom, meses, dow,
            dom_star, dow_star)

def proxima_execucao(expr, agora):
    minutos, horas, dom, meses, dow, dom_star, dow_star = _parse(expr)

    inicio = agora.replace(second=0, microsecond=0) + timedelta(minutes=1)
    tz = inicio.tzinfo
    dia = inicio.date()
    limite = dia + timedelta(days=366 * 5 + 1)
    primeiro = True

    while dia <= limite:
        if dia.month in meses:
            cron_dow = (dia.weekday() + 1) % 7
            bate_dom = dia.day in dom
            bate_dow = cron_dow in dow
            if dom_star and dow_star:
                ok = True
            elif dom_star:
                ok = bate_dow
            elif dow_star:
                ok = bate_dom
            else:
                ok = bate_dom or bate_dow
            if ok:
                if primeiro:
                    h0, m0 = inicio.hour, inicio.minute
                else:
                    h0, m0 = 0, 0
                for h in horas:
                    if h < h0:
                        continue
                    mmin = m0 if h == h0 else 0
                    for m in minutos:
                        if m >= mmin:
                            return datetime.combine(dia, time(h, m), tzinfo=tz)
        primeiro = False
        dia += timedelta(days=1)
    return None

import re

_HUNK_RE = re.compile(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@')

def _parse_hunks(diff):
    linhas = diff.split('\n')
    hunks = []
    i = 0
    n = len(linhas)
    while i < n:
        m = _HUNK_RE.match(linhas[i])
        if not m:
            i += 1
            continue
        a = int(m.group(1))
        b = int(m.group(2)) if m.group(2) is not None else 1
        c = int(m.group(3))
        d = int(m.group(4)) if m.group(4) is not None else 1
        old, new = [], []
        rem_old, rem_new = b, d
        ultimo = None  # tipo da última linha processada
        i += 1
        while i < n:
            ln = linhas[i]
            if ln.startswith('\\'):
                if ultimo in (' ', '-') and old and old[-1].endswith('\n'):
                    old[-1] = old[-1][:-1]
                if ultimo in (' ', '+') and new and new[-1].endswith('\n'):
                    new[-1] = new[-1][:-1]
                i += 1
                continue
            if rem_old == 0 and rem_new == 0:
                break
            if ln == '':
                tipo, conteudo = ' ', ''
            else:
                tipo, conteudo = ln[0], ln[1:]
            if tipo == ' ' and rem_old > 0 and rem_new > 0:
                old.append(conteudo + '\n')
                new.append(conteudo + '\n')
                rem_old -= 1
                rem_new -= 1
            elif tipo == '-' and rem_old > 0:
                old.append(conteudo + '\n')
                rem_old -= 1
            elif tipo == '+' and rem_new > 0:
                new.append(conteudo + '\n')
                rem_new -= 1
            else:
                break
            ultimo = tipo
            i += 1
        if rem_old != 0 or rem_new != 0:
            raise ValueError("hunk incompleto ou malformado")
        hunks.append((a, b, c, d, old, new))
    return hunks

def _split_lines(texto):
    if texto == '':
        return []
    partes = texto.split('\n')
    linhas = [p + '\n' for p in partes[:-1]]
    if partes[-1] != '':
        linhas.append(partes[-1])
    return linhas

def aplicar_patch(texto, diff):
    linhas = _split_lines(texto)
    hunks = _parse_hunks(diff)
    offset = 0
    limite = 0  # não reaplicar sobre região já modificada

    for a, b, c, d, old, new in hunks:
        if b == 0:
            base = a  # inserir após a linha a (0 => começo)
        else:
            base = a - 1
        esperado = base + offset
        k = len(old)
        maximo = len(linhas) - k

        pos = None
        if k == 0:
            pos = min(max(esperado, limite), len(linhas))
        else:
            if maximo >= limite:
                candidatos = range(limite, maximo + 1)
                melhor = None
                melhor_dist = None
                for p in candidatos:
                    if linhas[p:p + k] == old:
                        dist = abs(p - esperado)
                        if melhor is None or dist < melhor_dist or (
                            dist == melhor_dist and p < melhor
                        ):
                            melhor, melhor_dist = p, dist
                            if dist == 0:
                                break
                pos = melhor
            if pos is None:
                raise ValueError(
                    "hunk @@ -%d,%d +%d,%d @@ não pôde ser aplicado" % (a, b, c, d)
                )

        linhas[pos:pos + k] = new
        offset = pos + len(new) - (base + k)
        limite = pos + len(new)

    return ''.join(linhas)

import operator

_WS = " \t\f\r\n"
_OPS2 = ("**", "//")
_OPS1 = "+-*/%()"

def _read_digitpart(s, i):
    """Lê dígitos com '_' simples entre dígitos (como no Python). Retorna novo índice."""
    n = len(s)
    if i >= n or not s[i].isdigit() or not s[i].isascii():
        raise ValueError("número malformado")
    i += 1
    while i < n:
        c = s[i]
        if c.isascii() and c.isdigit():
            i += 1
        elif c == "_" and i + 1 < n and s[i + 1].isascii() and s[i + 1].isdigit():
            i += 2
        elif c == "_":
            raise ValueError("número malformado")
        else:
            break
    return i

def _is_digit(c):
    return c.isascii() and c.isdigit()

def _tokenize(s):
    tokens = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c in _WS:
            i += 1
            continue
        if _is_digit(c) or (c == "." and i + 1 < n and _is_digit(s[i + 1])):
            start = i
            is_float = False
            if c != ".":
                i = _read_digitpart(s, i)
                intpart = s[start:i].replace("_", "")
            else:
                intpart = ""
            if i < n and s[i] == ".":
                is_float = True
                i += 1
                if i < n and _is_digit(s[i]):
                    i = _read_digitpart(s, i)
                elif i < n and s[i] == "_":
                    raise ValueError("número malformado")
            if i < n and s[i] in "eE":
                is_float = True
                i += 1
                if i < n and s[i] in "+-":
                    i += 1
                i = _read_digitpart(s, i)
            if i < n and (s[i].isalnum() or s[i] in "_."):
                raise ValueError("número malformado")
            text = s[start:i].replace("_", "")
            if is_float:
                tokens.append(("num", float(text)))
            else:
                if len(intpart) > 1 and intpart[0] == "0" and intpart.strip("0") != "":
                    raise ValueError("zeros à esquerda não são permitidos")
                tokens.append(("num", int(text)))
            continue
        if s.startswith(_OPS2, i):
            tokens.append(("op", s[i:i + 2]))
            i += 2
            continue
        if c in _OPS1:
            tokens.append(("op", c))
            i += 1
            continue
        raise ValueError("caractere inválido: %r" % c)
    return tokens

class _Parser:
    def __init__(self, tokens):
        self.t = tokens
        self.p = 0

    def peek(self):
        if self.p < len(self.t):
            return self.t[self.p]
        return (None, None)

    def take_op(self, *ops):
        k, v = self.peek()
        if k == "op" and v in ops:
            self.p += 1
            return v
        return None

    def expr(self):
        left = self.term()
        while True:
            op = self.take_op("+", "-")
            if op is None:
                return left
            right = self.term()
            left = left + right if op == "+" else left - right

    def term(self):
        left = self.factor()
        while True:
            op = self.take_op("*", "/", "//", "%")
            if op is None:
                return left
            right = self.factor()
            if op == "*":
                left = left * right
            elif op == "/":
                left = operator.truediv(left, right)
            elif op == "//":
                left = left // right
            else:
                left = left % right

    def factor(self):
        op = self.take_op("+", "-")
        if op is not None:
            v = self.factor()
            return +v if op == "+" else -v
        return self.power()

    def power(self):
        base = self.atom()
        if self.take_op("**"):
            exp = self.factor()
            return base ** exp
        return base

    def atom(self):
        k, v = self.peek()
        if k == "num":
            self.p += 1
            return v
        if k == "op" and v == "(":
            self.p += 1
            val = self.expr()
            if not self.take_op(")"):
                raise ValueError("parêntese não fechado")
            return val
        raise ValueError("expressão malformada")

def calcular(expr):
    if not isinstance(expr, str):
        raise ValueError("a expressão deve ser uma string")
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("expressão vazia")
    parser = _Parser(tokens)
    result = parser.expr()
    if parser.p != len(tokens):
        raise ValueError("expressão malformada")
    return result

import re
from decimal import Decimal

def numero(txt):
    if txt is None or txt == "":
        return None

    txt = txt.replace("\xa0", " ").strip().lower()

    if not txt:
        return None

    if "nenhum" in txt or "sem" in txt:
        return 0

    match = re.search(r"(\d+(?:[.,]\d+)?)", txt)
    if not match:
        return None

    num_str = match.group(1)
    resto = txt[match.end():].strip()

    sufixos = {
        "k": 1000,
        "mil": 1000,
        "m": 1000000,
        "mi": 1000000,
        "b": 1000000000,
        "bi": 1000000000,
    }

    multiplicador = 1
    tem_sufixo = False
    for sufixo, valor in sufixos.items():
        if resto.startswith(sufixo):
            multiplicador = valor
            tem_sufixo = True
            break

    if tem_sufixo:
        num_str = num_str.replace(".", "").replace(",", ".")
    else:
        num_str = num_str.replace(".", "")
        if "," in num_str:
            num_str = num_str.replace(",", "")

    num = Decimal(num_str)
    resultado = num * multiplicador

    return int(resultado)

