            num_str = "".join(partes)
    else:
        num_str = num_str.replace(".", "").replace(",", "")

    num = Decimal(num_str)
    resultado = num * multiplicador

    return int(resultado)

from datetime import datetime, timedelta
from typing import List, Optional, Collection

def proximo_horario(
    horarios: List[str],
    agora: datetime,
    margem_min: int = 25,
    ocupados: Collection[datetime] = ()
) -> Optional[datetime]:
    if not horarios:
        return None

    # Parse e valida horários
    horarios_validos = []
    for h in horarios:
        try:
            partes = h.split(":")
            if len(partes) != 2:
                continue
            hora = int(partes[0])
            minuto = int(partes[1])
            if 0 <= hora <= 23 and 0 <= minuto <= 59:
                horarios_validos.append((hora, minuto))
        except (ValueError, AttributeError):
            continue

    if not horarios_validos:
        return None

    # Ordena horários
    horarios_validos.sort()

    # Converte ocupados para set de datetimes normalizados (sem segundos/microssegundos)
    ocupados_set = {dt.replace(second=0, microsecond=0) for dt in ocupados}

    # Calcula limite mínimo
    limite_minimo = agora + timedelta(minutes=margem_min)

    # Procura nos próximos 8 dias (hoje + 7)
    for dia_offset in range(8):
        dia_atual = agora.date() + timedelta(days=dia_offset)

        for hora, minuto in horarios_validos:
            candidato = datetime.combine(dia_atual, datetime.min.time()).replace(
                hour=hora, minute=minuto, second=0, microsecond=0
            )

            # Verifica se é >= limite_minimo e não está ocupado
            if candidato >= limite_minimo and candidato not in ocupados_set:
                return candidato

    return None

from datetime import timedelta

class Pausa:
    def __init__(self):
        self.minutos = 0
        self.fim = None

    def bloqueio(self, agora):
        if self.fim and agora < self.fim:
            # Bloqueio durante pausa ativa
            self.minutos = min(self.minutos * 2, 120)
        elif self.fim and agora - self.fim <= timedelta(minutes=60):
            # Bloqueio até 60 min após fim da pausa
            self.minutos = min(self.minutos * 2, 120)
        else:
            # Primeiro bloqueio ou mais de 60 min após fim da pausa
            self.minutos = 20
        self.fim = agora + timedelta(minutes=self.minutos)
        return self.minutos

    def pode_rodar(self, agora):
        return self.fim is None or agora >= self.fim

import json
import re

def extrair_texto(body):
    if not body:
        return ""

    # Remove prefixo anti-JSON
    body = re.sub(r"^\)\]\}'\s*", "", body)

    linhas = body.split('\n')
    texto_mais_longo = ""

    i = 0
    while i < len(linhas):
        linha = linhas[i].strip()

        # Pula linhas vazias
        if not linha:
            i += 1
            continue

        # Se for um número (tamanho do bloco), pula
        if linha.isdigit():
            i += 1
            continue

        # Tenta parsear como JSON array
        try:
            array = json.loads(linha)
            if not isinstance(array, list):
                i += 1
                continue

            # Procura entradas que começam com "wrb.fr"
            for entrada in array:
                if not isinstance(entrada, list) or len(entrada) < 3:
                    continue

                if entrada[0] != "wrb.fr":
                    continue

                # O índice 2 contém o JSON interno como string
                json_interno_str = entrada[2]

                if json_interno_str is None:
                    continue

                if not isinstance(json_interno_str, str):
                    continue

                try:
                    interno = json.loads(json_interno_str)

                    # Navega até interno[4][0][1][0]
                    texto = interno[4][0][1][0]

                    if isinstance(texto, str) and len(texto) > len(texto_mais_longo):
                        texto_mais_longo = texto

                except (json.JSONDecodeError, KeyError, IndexError, TypeError):
                    pass

        except json.JSONDecodeError:
            pass

        i += 1

    return texto_mais_longo

import re
from datetime import datetime, timedelta
from typing import Optional, Set, List

MONTH_NAMES = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
}

DAY_NAMES = {
    'sun': 0, 'mon': 1, 'tue': 2, 'wed': 3, 'thu': 4, 'fri': 5, 'sat': 6
}

def parse_field(field: str, min_val: int, max_val: int, names: dict = None) -> Set[int]:
    if not field or not field.strip():
        raise ValueError("Empty field")

    field = field.strip().lower()
    values = set()

    for part in field.split(','):
        part = part.strip()
        if not part:
            raise ValueError("Empty part in field")

        if names:
            for name, num in names.items():
                part = part.replace(name, str(num))

        step = 1
        if '/' in part:
            parts = part.split('/')
            if len(parts) != 2:
                raise ValueError(f"Invalid step syntax: {part}")
            part, step_str = parts
            try:
                step = int(step_str)
                if step <= 0:
                    raise ValueError(f"Step must be positive: {step}")
            except ValueError:
                raise ValueError(f"Invalid step value: {step_str}")

        if part == '*':
            start, end = min_val, max_val
        elif '-' in part:
            range_parts = part.split('-')
            if len(range_parts) != 2:
                raise ValueError(f"Invalid range syntax: {part}")
            try:
                start = int(range_parts[0])
                end = int(range_parts[1])
            except ValueError:
                raise ValueError(f"Invalid range values: {part}")
            if start < min_val or end > max_val or start > end:
                raise ValueError(f"Range out of bounds or invalid: {part}")
        else:
            try:
                num = int(part)
                if num < min_val or num > max_val:
                    raise ValueError(f"Value out of range: {num}")
                values.add(num)
                continue
            except ValueError:
                raise ValueError(f"Invalid field value: {part}")

        for val in range(start, end + 1, step):
            if min_val <= val <= max_val:
                values.add(val)

    return values

def proxima_execucao(expr: str, agora: datetime) -> Optional[datetime]:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes = parse_field(minute_field, 0, 59)
    hours = parse_field(hour_field, 0, 23)
    months = parse_field(month_field, 1, 12, MONTH_NAMES)

    dom_is_wildcard = dom_field.strip() == '*'
    dow_is_wildcard = dow_field.strip() == '*'

    doms = parse_field(dom_field, 1, 31) if not dom_is_wildcard else set(range(1, 32))
    dows_raw = parse_field(dow_field, 0, 7, DAY_NAMES) if not dow_is_wildcard else set(range(0, 7))

    dows = set()
    for d in dows_raw:
        if d == 7:
            dows.add(0)
        else:
            dows.add(d)

    current = agora.replace(second=0, microsecond=0) + timedelta(minutes=1)
    end_date = agora + timedelta(days=5*365)

    days_in_month = [0, 31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    while current <= end_date:
        if current.month not in months:
            if current.month == 12:
                current = datetime(current.year + 1, 1, 1, 0, 0)
            else:
                current = datetime(current.year, current.month + 1, 1, 0, 0)
            continue

        max_day = days_in_month[current.month]
        if current.month == 2:
            year = current.year
            is_leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
            max_day = 29 if is_leap else 28

        if current.day > max_day:
            if current.month == 12:
                current = datetime(current.year + 1, 1, 1, 0, 0)
            else:
                current = datetime(current.year, current.month + 1, 1, 0, 0)
            continue

        day_matches = False
        if dom_is_wildcard and dow_is_wildcard:
            day_matches = True
        elif dom_is_wildcard:
            day_matches = current.weekday() in dows if 6 in dows else (current.weekday() + 1) % 7 in dows
            if current.weekday() == 6 and 0 in dows:
                day_matches = True
        elif dow_is_wildcard:
            day_matches = current.day in doms and current.day <= max_day
        else:
            dom_match = current.day in doms and current.day <= max_day
            dow_match = current.weekday() in dows if 6 in dows else (current.weekday() + 1) % 7 in dows
            if current.weekday() == 6 and 0 in dows:
                dow_match = True
            day_matches = dom_match or dow_match

        if not day_matches:
            current = datetime(current.year, current.month, current.day, 0, 0) + timedelta(days=1)
            continue

        if current.hour not in hours:
            next_hour = min(h for h in hours if h > current.hour) if any(h > current.hour for h in hours) else min(hours)
            if next_hour > current.hour:
                current = datetime(current.year, current.month, current.day, next_hour, 0)
            else:
                current = datetime(current.year, current.month, current.day, 0, 0) + timedelta(days=1)
            continue

        if current.minute in minutes:
            return current

        next_minute = min(m for m in minutes if m > current.minute) if any(m > current.minute for m in minutes) else min(minutes)
        if next_minute > current.minute:
            current = datetime(current.year, current.month, current.day, current.hour, next_minute)
        else:
            next_hour = min(h for h in hours if h > current.hour) if any(h > current.hour for h in hours) else min(hours)
            if next_hour > current.hour:
                current = datetime(current.year, current.month, current.day, next_hour, min(minutes))
            else:
                current = datetime(current.year, current.month, current.day, 0, 0) + timedelta(days=1)

    return None

import re
from typing import List, Tuple, Optional

def aplicar_patch(texto: str, diff: str) -> str:
    linhas = texto.split('\n') if texto else ['']
    if texto and not texto.endswith('\n'):
        ultima_sem_newline = True
    else:
        ultima_sem_newline = False
        if linhas and linhas[-1] == '':
            linhas = linhas[:-1]

    linhas_diff = diff.split('\n')
    hunks = []
    i = 0

    while i < len(linhas_diff):
        linha = linhas_diff[i]
        if linha.startswith('---') or linha.startswith('+++'):
            i += 1
            continue

        match = re.match(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', linha)
        if match:
            old_start = int(match.group(1))
            old_count = int(match.group(2)) if match.group(2) else 1
            new_start = int(match.group(3))
            new_count = int(match.group(4)) if match.group(4) else 1

            i += 1
            hunk_linhas = []

            while i < len(linhas_diff):
                if linhas_diff[i].startswith('@@'):
                    break
                if linhas_diff[i].startswith('---') or linhas_diff[i].startswith('+++'):
                    break

                hunk_linhas.append(linhas_diff[i])
                i += 1

            hunks.append((old_start, old_count, new_start, new_count, hunk_linhas))
        else:
            i += 1

    offset = 0

    for old_start, old_count, new_start, new_count, hunk_linhas in hunks:
        contexto = []
        removidas = []
        adicionadas = []

        j = 0
        while j < len(hunk_linhas):
            linha = hunk_linhas[j]
            tem_newline = True

            if j + 1 < len(hunk_linhas) and hunk_linhas[j + 1].startswith('\\ No newline'):
                tem_newline = False

            if linha.startswith(' '):
                contexto.append((linha[1:], tem_newline))
                removidas.append((linha[1:], tem_newline))
                adicionadas.append((linha[1:], tem_newline))
            elif linha.startswith('-'):
                removidas.append((linha[1:], tem_newline))
            elif linha.startswith('+'):
                adicionadas.append((linha[1:], tem_newline))
            elif linha.startswith('\\'):
                pass

            if j + 1 < len(hunk_linhas) and hunk_linhas[j + 1].startswith('\\ No newline'):
                j += 2
            else:
                j += 1

        posicao_esperada = old_start - 1 + offset
        posicao_aplicar = None

        if old_count == 0:
            posicao_aplicar = posicao_esperada
        else:
            if posicao_esperada >= 0 and posicao_esperada + len(removidas) <= len(linhas):
                match = True
                for k, (conteudo, _) in enumerate(removidas):
                    if posicao_esperada + k >= len(linhas) or linhas[posicao_esperada + k] != conteudo:
                        match = False
                        break

                if match:
                    posicao_aplicar = posicao_esperada

            if posicao_aplicar is None:
                melhor_pos = None
                melhor_dist = float('inf')

                for pos in range(len(linhas) - len(removidas) + 1):
                    match = True
                    for k, (conteudo, _) in enumerate(removidas):
                        if linhas[pos + k] != conteudo:
                            match = False
                            break

                    if match:
                        dist = abs(pos - posicao_esperada)
                        if dist < melhor_dist:
                            melhor_dist = dist
                            melhor_pos = pos

                if melhor_pos is not None:
                    posicao_aplicar = melhor_pos
                else:
                    raise ValueError(f"Não foi possível aplicar hunk na linha {old_start}")

        novas_linhas = linhas[:posicao_aplicar]
        for conteudo, _ in adicionadas:
            novas_linhas.append(conteudo)
        novas_linhas.extend(linhas[posicao_aplicar + len(removidas):])

        linhas = novas_linhas
        offset += len(adicionadas) - len(removidas)

    if hunks:
        _, _, _, _, ultima_hunk_linhas = hunks[-1]
        ultima_linha_diff = None
        tem_newline_final = True

        for j in range(len(ultima_hunk_linhas) - 1, -1, -1):
            linha = ultima_hunk_linhas[j]
            if linha.startswith('\\'):
                continue
            if linha.startswith('+') or linha.startswith(' '):
                ultima_linha_diff = linha
                if j + 1 < len(ultima_hunk_linhas) and ultima_hunk_linhas[j + 1].startswith('\\ No newline'):
                    tem_newline_final = False
                break

        if ultima_linha_diff:
            if tem_newline_final:
                return '\n'.join(linhas) + '\n' if linhas else '\n'
            else:
                return '\n'.join(linhas) if linhas else ''

    if ultima_sem_newline:
        return '\n'.join(linhas) if linhas else ''
    else:
        return '\n'.join(linhas) + '\n' if linhas else '\n'

