import re
from typing import Union

def calcular(expr: str) -> Union[int, float]:
    if not expr or not expr.strip():
        raise ValueError("Expressão vazia")

    # Tokenizador
    token_pattern = r'\d+\.?\d*[eE][+-]?\d+|\d*\.\d+|\d+\.|\d+|[+\-*/%()]|\*\*|\s+'
    tokens = []
    pos = 0

    for match in re.finditer(token_pattern, expr):
        if match.start() != pos:
            raise ValueError(f"Caractere inválido na posição {pos}")
        token = match.group()
        if not token.isspace():
            tokens.append(token)
        pos = match.end()

    if pos != len(expr):
        raise ValueError(f"Caractere inválido na posição {pos}")

    if not tokens:
        raise ValueError("Expressão vazia")

    # Validar números
    for token in tokens:
        if token not in ['+', '-', '*', '/', '//', '%', '**', '(', ')']:
            if re.match(r'^\d', token):
                if token.startswith('0') and len(token) > 1 and token[1].isdigit():
                    raise ValueError(f"Zero à esquerda inválido: {token}")

    # Parser recursivo descendente
    index = [0]

    def peek():
        return tokens[index[0]] if index[0] < len(tokens) else None

    def consume():
        token = peek()
        index[0] += 1
        return token

    def parse_number():
        token = peek()
        if token and token not in ['+', '-', '*', '/', '//', '%', '**', '(', ')']:
            consume()
            if 'e' in token.lower():
                return float(token)
            elif '.' in token:
                return float(token)
            else:
                return int(token)
        return None

    def parse_atom():
        token = peek()
        if token == '(':
            consume()
            result = parse_expression()
            if peek() != ')':
                raise ValueError("Parêntese não fechado")
            consume()
            return result

        num = parse_number()
        if num is not None:
            return num

        raise ValueError(f"Token inesperado: {token}")

    def parse_unary():
        token = peek()
        if token in ['+', '-']:
            op = consume()
            operand = parse_unary()
            if op == '-':
                return -operand
            return operand
        return parse_atom()

    def parse_power():
        left = parse_unary()
        if peek() == '**':
            consume()
            right = parse_power()
            return left ** right
        return left

    def parse_term():
        left = parse_power()
        while peek() in ['*', '/', '//', '%']:
            op = consume()
            right = parse_power()
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                left = left / right
            elif op == '//':
                if right == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                left = left // right
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                left = left % right
        return left

    def parse_expression():
        left = parse_term()
        while peek() in ['+', '-']:
            op = consume()
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    result = parse_expression()

    if index[0] < len(tokens):
        raise ValueError(f"Token inesperado: {tokens[index[0]]}")

    return result

