from typing import Union

def calcular(expr: str) -> Union[int, float]:
    if not expr or not expr.strip():
        raise ValueError("Expressão vazia")

    # Tokenizador
    tokens = []
    i = 0

    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue

        # Operadores de dois caracteres
        if i + 1 < len(expr):
            two_char = expr[i:i+2]
            if two_char in ['**', '//', '<=', '>=', '==', '!=']:
                tokens.append(two_char)
                i += 2
                continue

