        return left

    def parse_expression():
        left = parse_term()
        while peek() in ['+', '-']:
            op = consume()
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    result = parse_expression()

    if index[0] < len(tokens):
        raise ValueError(f"Token inesperado: {tokens[index[0]]}")

    return result

