from typing import Collection, Iterable, Optional

def proximo_horario(
    horarios: Iterable[str],
    agora: datetime,
    margem_min: int = 25,
    ocupados: Collection[datetime] = (),
) -> Optional[datetime]:
    validos = set()
    for item in horarios:
        try:
            partes = item.split(":")
            if len(partes) == 2:
                h, m = int(partes[0]), int(partes[1])
                if 0 <= h <= 23 and 0 <= m <= 59:
                    validos.add((h, m))
        except (ValueError, AttributeError):
            continue

    if not validos:
        return None

    horarios_ordenados = sorted(validos)
    limite_minimo = agora + timedelta(minutes=margem_min)
    ocupados_set = set(ocupados)
    data_base = agora.date()

    for dia_offset in range(8):
        data_atual = data_base + timedelta(days=dia_offset)
        for hora, minuto in horarios_ordenados:
            candidato = datetime(
                data_atual.year,
                data_atual.month,
                data_atual.day,
                hora,
                minuto,
                0,
                0,
            )
            if candidato >= limite_minimo and candidato not in ocupados_set:
                return candidato

    return None

