class Pausa:
    def __init__(self):
        self.minutos = 0
        self.fim = None

    def bloqueio(self, agora):
        if self.fim is not None and agora <= self.fim + timedelta(minutes=60):
            self.minutos = min(120, self.minutos * 2)
        else:
            self.minutos = 20
        self.fim = agora + timedelta(minutes=self.minutos)
        return self.minutos

    def pode_rodar(self, agora):
        return self.fim is None or agora >= self.fim

