        linha = linha.strip()
        if not linha.startswith("["):
            continue

        try:
            dados = json.loads(linha)
        except Exception:
            continue

        if not isinstance(dados, list):
            continue

        for item in dados:
            if not (isinstance(item, list) and len(item) > 2 and item[0] == "wrb.fr"):
                continue

            payload = item[2]
            if not isinstance(payload, str):
                continue

            try:
                interno = json.loads(payload)
            except Exception:
                continue

            try:
                texto = interno[4][0][1][0]
                if isinstance(texto, str) and len(texto) > len(maior_texto):
                    maior_texto = texto
            except (IndexError, TypeError):
                continue

    return maior_texto

