def _parse_field(field_str, min_val, max_val, name_map=None):
    if not field_str:
        raise ValueError("Campo vazio")

    def convert_val(token):
        token_lower = token.lower()
        if name_map and token_lower in name_map:
            return name_map[token_lower]
        if not token.isdigit():
            raise ValueError(f"Valor inválido: {token}")
        return int(token)

    values = set()
    for item in field_str.split(","):
        if not item:
            raise ValueError("Subcampo vazio na lista")
        step_parts = item.split("/")
        if len(step_parts) > 2:
            raise ValueError("Múltiplas barras no passo")
        if len(step_parts) == 2:
            if not step_parts[1].isdigit():
                raise ValueError("Passo deve ser numérico")
            step = int(step_parts[1])
            if step <= 0:
                raise ValueError("Passo deve ser maior que zero")
        else:
            step = 1

        range_part = step_parts[0]
        if range_part == "*":
            start, end = min_val, max_val
        elif "-" in range_part:
            r_parts = range_part.split("-")
            if len(r_parts) != 2:
                raise ValueError("Faixa inválida")
            start = convert_val(r_parts[0])
            end = convert_val(r_parts[1])
            if start > end:
                raise ValueError("Início da faixa maior que o fim")
        else:
            val = convert_val(range_part)
            if len(step_parts) == 2:
                start, end = val, max_val
            else:
                start, end = val, val

        if start < min_val or end > max_val:
            raise ValueError(
                f"Valor fora da faixa [{min_val}, {max_val}]: {start}-{end}"
            )

        for v in range(start, end + 1, step):
            values.add(v)

    if not values:
        raise ValueError("Nenhum valor gerado para o campo")
    return values

