_NUM_RE = re.compile(r'^(?:(\d+(?:\.\d*)?(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?))$')
_TOKEN_RE = re.compile(
    r'\s*(?:'
    r'(\d+(?:\.\d*)?(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)'  # Grupo 1: Números
    r'|(\*\*|//|[+\-*/%()])'                                     # Grupo 2: Operadores
    r'|(\S)'                                                     # Grupo 3: Inválidos
    r')'
)

def calcular(expr: str):
    if not isinstance(expr, str):
        raise ValueError("A expressão deve ser uma string.")

    tokens = []
    pos = 0
    length = len(expr)

    while pos < length:
        match = _TOKEN_RE.match(expr, pos)
        if not match:
            break
        pos = match.end()

        num, op, invalid = match.groups()
        if invalid:
            raise ValueError(f"Caractere inválido: {invalid!r}")
        elif num is not None:
            if num.startswith('0') and len(num) > 1 and num[1].isdigit():
                raise ValueError(f"Número com zero à esquerda inválido: {num!r}")
            if '.' in num or 'e' in num or 'E' in num:
                tokens.append(('NUM', float(num)))
            else:
                tokens.append(('NUM', int(num)))
        elif op is not None:
            tokens.append((op, op))

    if pos < length or not tokens:
        raise ValueError("Expressão inválida ou vazia.")

    idx = 0
    total_tokens = len(tokens)

    def peek():
        if idx < total_tokens:
            return tokens[idx]
        return (None, None)

    def consume(expected=None):
        nonlocal idx
        tok_type, val = peek()
        if tok_type is None:
            raise ValueError("Fim inesperado da expressão.")
        if expected is not None and tok_type != expected:
            raise ValueError(f"Esperado {expected!r}, obtido {tok_type!r}.")
        idx += 1
        return val

    def parse_expr():
        res = parse_sum()
        if idx < total_tokens:
            raise ValueError(f"Token inesperado após expressão: {tokens[idx]!r}")
        return res

    def parse_sum():
        left = parse_term()
        while peek()[0] in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        left = parse_factor()
        while peek()[0] in ('*', '/', '//', '%'):
            op = consume()
            right = parse_factor()
            if op == '*':
                left = left * right
            elif op == '/':
                left = left / right
            elif op == '//':
                left = left // right
            elif op == '%':
                left = left % right
        return left

    def parse_factor():
        tok_type, _ = peek()
        if tok_type == '+':
            consume()
            return +parse_factor()
        if tok_type == '-':
            consume()
            return -parse_factor()
        return parse_power()

    def parse_power():
        left = parse_atom()
        if peek()[0] == '**':
            consume()
            right = parse_factor()
            return left ** right
        return left

    def parse_atom():
        tok_type, val = peek()
        if tok_type == 'NUM':
            consume()
            return val
        if tok_type == '(':
            consume('(')
            res = parse_sum()
            consume(')')
            return res
        raise ValueError(f"Esperado número ou parêntese, obtido {tok_type!r}.")

    return parse_expr()
